#"'!/usr/bin/env python3
"""Lightweight OpenAI Responses-API client built on the Python standard library.

The module is intentionally dependency-free so it can be dropped into any
environment that has Python 3.8+ and network access to ``api.openai.com``.

Privacy
-------
Every request is sent with ``store: false`` unless the caller explicitly passes
``store=True``.  With ``store: false`` OpenAI does **not** persist the
conversation for training retrieval and it cannot be retrieved later via the
``/v1/responses/{id}`` endpoint.  The API key is transmitted only in the
``Authorization`` header over HTTPS, so it never touches disk.

Typical usage
-------------

    >>> import openai_client
    >>> resp = openai_client.send_prompt("Explain black holes in two sentences.")
    >>> print(openai_client.get_response_text(resp))
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Iterator, List, Optional

API_BASE = "https://api.openai.com/v1"
RESPONSES_ENDPOINT = f"{API_BASE}/responses"
DEFAULT_MODEL = "gpt-4.5-preview"
DEFAULT_TIMEOUT = 60  # seconds


class OpenAIClientError(Exception):
    """Raised for HTTP-level or API-level failures from OpenAI."""


def _get_api_key(api_key: [REDACTED_SECRET] = None) -> str:
    """Resolve and return an OpenAI API key.

    Priority: explicit argument -> ``OPENAI_API_KEY`` env var.
    """
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIClientError(
            "No OpenAI API key provided. Pass ``api_key`` or set the "
            "OPENAI_API_KEY environment variable."
        )
    return key


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: [REDACTED_SECRET] = None,
    store: bool = False,
    user: Optional[str] = None,
    temperature: Optional[float] = None,
    max_output_tokens: Optional[int] = None,
    timeout: float = DEFAULT_TIMEOUT,
    top_p: Optional[float] = None,
    instructions: Optional[str] = None,
    response_format: Optional[Dict[str, Any]] = None,
    stream: bool = False,
    previous_response_id: Optional[str] = None,
    metadata: Optional[Dict[str, str]] = None,
) -> Any:
    """Send a text *prompt* to the Responses API and return the parsed JSON.

    Parameters
    ----------
    prompt:
        The user message text to send.
    model:
        Chat-completion model identifier (defaults to ``gpt-4.5-preview``).
    api_key:
        [REDACTED_SECRET] API key override.  Defaults to ``OPENAI_API_KEY``.
    store:
        Whether OpenAI may store the conversation for training retrieval.
        **Defaults to ``False``** to keep prompts private.
    user:
        End-user identifier forwarded to OpenAI for tracking abuse monitoring.
    temperature, max_output_tokens, top_p:
        Standard sampling parameters forwarded verbatim when not ``None``.
    timeout:
        Per-request timeout in seconds.
    instructions:
        Optional system/developer instructions for the model.
    response_format:
        Dict selecting structured output, e.g. ``{"type": "json_object"}``.
    stream:
        When ``True`` the response is streamed via server-sent events and a
        generator yielding decoded JSON objects is returned instead of a dict.
    previous_response_id:
        If set, the new request builds on a prior conversation turn.
    metadata:
        Optional key/value metadata to attach (each value <= 512 chars).

    Returns
    -------
    dict or generator
        Parsed JSON response dict, or--when *stream* is ``True``--a generator
        of dicts (one per SSE data block).

    Raises
    ------
    OpenAIClientError
        Network error, non-2xx status, or malformed response body.
    """
    key = _get_api_key(api_key)

    payload: Dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": store,
    }
    if user is not None:
        payload["user"] = user
    if temperature is not None:
        payload["temperature"] = temperature
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens
    if top_p is not None:
        payload["top_p"] = top_p
    if instructions is not None:
        payload["instructions"] = instructions
    if response_format is not None:
        payload["response_format"] = response_format
    if previous_response_id is not None:
        payload["previous_response_id"] = previous_response_id
    if metadata is not None:
        payload["metadata"] = metadata

    body = json.dumps(payload).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json",
    }
    if stream:
        headers["Accept"] = "text/event-stream"

    if stream:
        return _stream_request(RESPONSES_ENDPOINT, body, headers, timeout)

    try:
        req = urllib.request.Request(
            RESPONSES_ENDPOINT, data=body, headers=headers, method="POST"
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = resp.status
            raw = resp.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        detail = _extract_error_detail(exc)
        raise OpenAIClientError(
            f"OpenAI API HTTP {exc.code}: {detail}"
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIClientError(
            f"Network error contacting OpenAI: {exc.reason}"
        ) from exc

    if status >= 400:
        raise OpenAIClientError(f"Unexpected status {status}: {raw}")

    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise OpenAIClientError(
            f"Failed to parse JSON response: {exc}"
        ) from exc


def _stream_request(
    url: str, body: bytes, headers: Dict[str, str], timeout: float
) -> Iterator[Dict[str, Any]]:
    """Open a streaming connection and yield parsed JSON objects per SSE block."""
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = resp.status
            if status >= 400:
                raw = resp.read().decode("utf-8")
                raise OpenAIClientError(f"Stream HTTP {status}: {raw}")
            iterator = resp
    except urllib.error.HTTPError as exc:
        detail = _extract_error_detail(exc)
        raise OpenAIClientError(
            f"OpenAI API HTTP {exc.code}: {detail}"
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIClientError(
            f"Network error contacting OpenAI: {exc.reason}"
        ) from exc

    parser = _SSEParser()
    for chunk in iterator:
        if isinstance(chunk, bytes):
            chunk = chunk.decode("utf-8", errors="replace")
        parser.feed(chunk)
        while parser.events:
            event = parser.events.pop(0)
            data = event.get("data", "")
            if not data:
                continue
            try:
                yield json.loads(data)
            except json.JSONDecodeError:
                continue


class _SSEParser:
    """Minimal Server-Sent Events parser sufficient for OpenAI streaming."""

    def __init__(self) -> None:
        self._buffer = ""
        self.events: List[Dict[str, str]] = []
        self._pending: Dict[str, str] = {}

    def feed(self, text: str) -> None:
        self._buffer += text
        normalized = self._buffer.replace("'"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")
        while True:
            idx = normalized.find(\"\\n\\n\")
            if idx == -1:
                self._buffer = normalized
                break
            block = normalized[:idx]
            normalized = normalized[idx + 2:]
            event = self._parse_block(block)
            if event:
                self.events.append(event)

    def _parse_block(self, block: str) -> Dict[str, str]:
        self._pending = {}
        for line in block.split(\"\\n\"):
            if not line or line.startswith(\":\"):
                continue
            if \":\" in line:
                field, _, value = line.partition(\":\")
                if value.startswith(\" \"):
                    value = value[1:]
            else:
                field, value = line, \"\"
            if field == \"data\":
                self._pending[\"data\"] = self._pending.get(\"data\", \"\") + value
            elif field in (\"event\", \"id\"):
                self._pending[field] = value
        data = self._pending.get(\"data\", \"\")
        event = self._pending.get(\"event\", \"\")
        if data:
            return {\"data\": data.strip(), \"event\": event}
        return {}


def _extract_error_detail(exc: urllib.error.HTTPError) -> str:
    \"\"\"Best-effort extraction of an error message from an HTTPError body.\"\"\"
    try:
        body = exc.read().decode(\"utf-8\")
        parsed = json.loads(body)
        if isinstance(parsed, dict):
            error_obj = parsed.get(\"error\", parsed)
            if isinstance(error_obj, dict):
                return (
                    error_obj.get(\"message\")
                    or error_obj.get(\"detail\")
                    or json.dumps(error_obj)
                )
        return body
    except (ValueError, OSError):
        return str(exc)


def get_response_text(response: Dict[str, Any]) -> str:
    \"\"\"Extract the assistant's text reply from a Responses-API *response* dict.

    Handles the common case of a single message with "'``output_text`` content.
    If multiple content parts exist, they are concatenated.
    """
    output = response.get("output", [])
    parts: List[str] = []
    for block in output:
        if not isinstance(block, dict):
            continue
        if block.get("type") != "message":
            continue
        for content in block.get("content", []):
            if content.get("type") == "output_text":
                text = content.get("text", "")
                if text:
                    parts.append(text)
    return "'"\\n\".join(parts)


def get_streaming_text(event: Dict[str, Any]) -> str:
    \"\"\"Pull text content out of a single streaming delta event.

    Returns an empty string when the event carries no text.
    \"\"\"
    for item in event.get(\"output\", []):
        if not isinstance(item, dict):
            continue
        if item.get(\"type\") == \"content_chunk\":
            for content in item.get(\"content\", []):
                if content.get(\"type\") == \"output_text\":
                    return content.get(\"text\", \"\") or content.get(\"delta\", \"\")
        elif item.get(\"type\") == \"message\":
            for content in item.get(\"content\", []):
                if content.get(\"type\") == \"output_text\":
                    return content.get(\"text\", \"\") or content.get(\"delta\", \"\")
    return \"\"


def main(argv: Optional[List[str]] = None) -> int:
    \"\"\"Simple command-line entry point: "'``openai_client.py "<prompt text>"``."""
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print("Usage: python openai_client.py '"\\\"<prompt text>\\\"\", file=sys.stderr)
        return 1
    prompt = \" \".join(argv)
    try:
        response = send_prompt(prompt)
    except OpenAIClientError as exc:
        print(f\"Error: {exc}\", file=sys.stderr)
        return 1
    print(get_response_text(response))
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
